package com.taxcalculator.service;
import com.taxcalculator.domain.*; import com.taxcalculator.web.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class ReportService { private final VehicleRepository vehicles; private final VehicleFactRepository facts; private final ReportFlagRepository flags; private final SourceQueryRepository queries; private final RawSourceDataRepository raw;
 public ReportService(VehicleRepository v,VehicleFactRepository f,ReportFlagRepository fl,SourceQueryRepository q,RawSourceDataRepository r){vehicles=v;facts=f;flags=fl;queries=q;raw=r;}
 @Transactional(readOnly=true) public VehicleReportResponse report(UUID vehicleId){Vehicle vehicle=vehicles.findById(vehicleId).orElseThrow(()->new NotFoundException("Vehicle not found"));List<FactResponse> all=facts.findByVehicleId(vehicleId).stream().map(f->new FactResponse(f.getId(),f.getFactType(),f.getValue(),f.getObservedAt(),f.getSourceId(),f.getSourceQueryId())).toList();Map<FactType,List<FactResponse>> grouped=new LinkedHashMap<>();all.stream().sorted(Comparator.comparing(FactResponse::observedAt,Comparator.nullsLast(Comparator.naturalOrder()))).forEach(f->grouped.computeIfAbsent(f.type(),x->new ArrayList<>()).add(f));return new VehicleReportResponse(vehicleId,vehicle.getVin(),vehicle.getPrimaryPlate(),vehicle.getPrimaryCountry(),grouped,flags.findByVehicleId(vehicleId).stream().map(f->new FlagResponse(f.getId(),f.getFlagType(),List.of(f.getRelatedFactIds()),f.getDescription())).toList());}
 @Transactional(readOnly=true) public List<SourceQueryResponse> sourceQueries(UUID lookupId){return queries.findByLookupIdOrderByStartedAt(lookupId).stream().map(q->new SourceQueryResponse(q.getId(),q.getSourceId(),q.getStatus(),q.getStartedAt(),q.getCompletedAt(),q.getErrorMessage(),raw.findBySourceQueryId(q.getId()).map(RawSourceData::getId).orElse(null))).toList();}
 @Transactional(readOnly=true) public Object raw(UUID queryId){return raw.findBySourceQueryId(queryId).map(RawSourceData::getPayload).orElseThrow(()->new NotFoundException("Raw payload not found"));}
}
